from html import escape

from app.branding import ACCENT_COLOR, APP_NAME, COMPANY_NAME, LOGO_URL, PRIMARY_COLOR


def page(title: str, body: str) -> str:
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)} · {escape(APP_NAME)}</title><style>
:root{{--bg:#f5f7fa;--card:#fff;--ink:#172033;--muted:#667085;--line:#e3e8ef;--accent:{ACCENT_COLOR};--brand:{PRIMARY_COLOR};--ok:#137a42;--shadow:0 8px 28px rgba(16,24,40,.06)}}*{{box-sizing:border-box}}body{{margin:0;font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;background:var(--bg);color:var(--ink)}}header{{background:#fff;color:var(--ink);padding:0 24px;border-bottom:1px solid var(--line);position:sticky;top:0;z-index:20;box-shadow:0 2px 10px rgba(16,24,40,.035)}}nav{{max-width:1240px;min-height:74px;margin:auto;display:flex;align-items:center;justify-content:space-between;gap:22px}}.brand{{display:flex;align-items:center;gap:12px;text-decoration:none;color:var(--brand)}}.brand img{{width:48px;height:48px;object-fit:contain;border-radius:8px}}.brand-copy{{display:flex;flex-direction:column;line-height:1.1}}.brand-title{{font-weight:800;font-size:17px;letter-spacing:-.2px}}.brand-company{{font-size:10px;color:var(--muted);margin-top:4px;text-transform:uppercase;letter-spacing:.8px}}.nav-links{{display:flex;align-items:center;gap:6px}}nav .nav-links a{{color:#344054;text-decoration:none;margin:0;padding:9px 12px;border-radius:9px;font-weight:600;font-size:14px}}nav .nav-links a:hover{{background:#eef4f8;color:var(--brand)}}main{{max-width:1240px;margin:32px auto;padding:0 24px 44px}}.card{{background:var(--card);border:1px solid var(--line);border-radius:16px;padding:22px;box-shadow:var(--shadow);margin-bottom:18px}}.grid{{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:16px}}.stat{{font-size:30px;font-weight:780;color:var(--brand)}}.muted{{color:var(--muted)}}.row{{display:flex;gap:12px;align-items:center;flex-wrap:wrap}}.stack{{display:flex;flex-direction:column;gap:10px;align-items:stretch}}.split-panel{{display:grid;grid-template-columns:minmax(150px,190px) minmax(0,1fr);gap:26px;align-items:start}}.action-list{{display:flex;flex-direction:column;gap:9px;align-items:stretch;max-width:420px}}.action-list .button{{display:flex;justify-content:space-between;gap:18px;width:100%;text-align:left}}input,select{{padding:11px 12px;border:1px solid #cfd6df;border-radius:9px;min-width:220px;background:white;color:var(--ink)}}button,.button{{background:var(--accent);color:white;border:0;border-radius:9px;padding:11px 15px;font-weight:650;cursor:pointer;text-decoration:none;display:inline-block;transition:transform .08s ease,opacity .15s ease,box-shadow .15s ease}}button:hover,.button:hover{{opacity:.94;box-shadow:0 5px 14px rgba(0,0,0,.09)}}.secondary{{background:#344054}}table{{width:100%;border-collapse:collapse}}th,td{{text-align:left;padding:12px;border-bottom:1px solid var(--line);vertical-align:top}}.pill{{display:inline-block;padding:5px 9px;border-radius:999px;background:#eef3ff;color:#244aa5;font-size:12px}}h1,h2{{margin-top:0;letter-spacing:-.4px}}h3{{margin-top:0}}code{{font-size:12px}}@media(max-width:760px){{header{{padding:0 14px}}nav{{min-height:66px}}.brand-company{{display:none}}.brand img{{width:40px;height:40px}}.nav-links a{{padding:8px 7px;font-size:12px}}main{{padding:0 14px 32px;margin-top:22px}}.split-panel{{grid-template-columns:1fr}}table{{display:block;overflow:auto}}}}
</style></head><body><header><nav><a class="brand" href="/"><img src="{escape(LOGO_URL)}" alt="{escape(APP_NAME)} logo"><span class="brand-copy"><span class="brand-title">{escape(APP_NAME)}</span><span class="brand-company">{escape(COMPANY_NAME)}</span></span></a><div class="nav-links"><a href="/">Home</a><a href="/ui/projects">Projects</a><a href="/ui/accounts">Storage Accounts</a></div></nav></header><main>{body}</main></body></html>'''
